    [DataRow(10.00, 1, 0.0,  10.00,  DisplayName = "Single item, no tax")]
    [DataRow(10.00, 2, 0.0,  20.00,  DisplayName = "Two items, no tax")]
    [DataRow(10.00, 1, 0.10, 11.00,  DisplayName = "Single item, 10% tax")]
    [DataRow(25.50, 3, 0.08, 82.62,  DisplayName = "Fractional price, 8% tax")]
    [DataRow(0.00,  5, 0.10, 0.00,   DisplayName = "Zero price yields zero")]
    [DataRow(10.00, 0, 0.10, 0.00,   DisplayName = "Zero quantity yields zero")]
    [DataRow(99.99, 1, 1.0,  199.98, DisplayName = "Max tax rate (100%)")]
    public void CalculateTotal_WithValidInputs_ReturnsExpected(
        double unitPrice, int quantity, double taxRate, double expected)
    {
        var result = _calculator.CalculateTotal((decimal)unitPrice, quantity, (decimal)taxRate);

        Assert.AreEqual((decimal)expected, result);
    }

    // ── CalculateTotal: DynamicData-driven boundary / error tests ───────

    public static IEnumerable<object[]> InvalidCalculateTotalInputs =>
    [
        [/* unitPrice */ -1m, /* qty */ 1,  /* tax */ 0.1m, typeof(ArgumentOutOfRangeException), "Negative price"],
        [/* unitPrice */  1m, /* qty */ -1, /* tax */ 0.1m, typeof(ArgumentOutOfRangeException), "Negative quantity"],
        [/* unitPrice */  1m, /* qty */ 1,  /* tax */ -0.1m, typeof(ArgumentOutOfRangeException), "Negative tax"],
        [/* unitPrice */  1m, /* qty */ 1,  /* tax */ 1.01m, typeof(ArgumentOutOfRangeException), "Tax > 1"],
    ];

    [TestMethod]
    [DynamicData(nameof(InvalidCalculateTotalInputs), DynamicDataDisplayName = nameof(GetInvalidInputDisplayName))]
    public void CalculateTotal_WithInvalidInputs_Throws(
        decimal unitPrice, int quantity, decimal taxRate, Type expectedException, string _)
    {
        Assert.ThrowsExactly(
            expectedException,
            () => _calculator.CalculateTotal(unitPrice, quantity, taxRate));
    }

    public static string GetInvalidInputDisplayName(MethodInfo _, object[] data) => (string)data[4];

    // ── ApplyDiscount: DataRow-driven tests ─────────────────────────────

    [TestMethod]
    [DataRow(100.00, 0.0,   100.00, DisplayName = "0% discount — full price")]
    [DataRow(100.00, 50.0,  50.00,  DisplayName = "50% discount")]
    [DataRow(100.00, 100.0, 0.00,   DisplayName = "100% discount — free")]
    [DataRow(200.00, 25.0,  150.00, DisplayName = "25% off $200")]
    [DataRow(0.00,   50.0,  0.00,   DisplayName = "Zero price stays zero")]
    [DataRow(79.99,  10.0,  71.991, DisplayName = "Fractional result")]
    public void ApplyDiscount_WithValidInputs_ReturnsExpected(
        double price, double discountPercent, double expected)
    {
        var result = _calculator.ApplyDiscount((decimal)price, (decimal)discountPercent);

        Assert.AreEqual((decimal)expected, result);
    }

    // ── ApplyDiscount: DynamicData from method ──────────────────────────

    public static IEnumerable<object[]> InvalidDiscountInputs()
    {
        yield return [100m, -1m,   "Negative discount"];
        yield return [100m, 100.1m, "Discount > 100%"];
    }

    [TestMethod]
    [DynamicData(nameof(InvalidDiscountInputs), DynamicDataSourceType.Method,
        DynamicDataDisplayName = nameof(GetDiscountDisplayName))]
    public void ApplyDiscount_WithInvalidDiscount_ThrowsArgumentOutOfRange(
        decimal price, decimal discountPercent, string _)
    {
        Assert.ThrowsExactly<ArgumentOutOfRangeException>(
            () => _calculator.ApplyDiscount(price, discountPercent));
    }

    public static string GetDiscountDisplayName(MethodInfo _, object[] data) => (string)data[2];
}

